export default function FinanceAuthorityWorkspace({ scene, snapshot, defaultPlane }: Props) {
  const router = useRouter()
  const params = useSearchParams()
  const planes = FINANCE_AUTHORITY_PLANES[scene]
  const activePlane = params.get('plane') || defaultPlane || planes[0]?.key || ''
  const copy = SCENE_COPY[scene]
  const [action, setAction] = useState<ActionDefinition | null>(null)
  const records = snapshot.records
  const actions = useMemo(() => ACTIONS[scene].map((item) => ({ ...item, fields: resolveFinanceFields(item.fields, snapshot) })), [scene, snapshot])

  function completed(result: FinanceAuthorityCommandResult) {
    dispatchCustomerToast({ title: result.state === 'approval_required' ? 'Approbation requise' : 'Opération financière réalisée', message: result.message, tone: result.state === 'approval_required' ? 'warning' : 'success', progress: 100, durationMs: 3000 })
    router.refresh()
  }

  return <section className={styles.workspace} data-scene={scene}>
    <header className={styles.crown}>
      <div className={styles.crownCopy}><span className={styles.eyebrow}>{copy.eyebrow}</span><h1 className={styles.title}>{copy.title}</h1><p className={styles.subtitle}>{copy.subtitle}</p></div>
      <div className={styles.crownMeta}><span className={styles.liveChip}><i className={styles.liveDot}/> Autorité runtime active</span><span className={styles.contextChip}>{snapshot.schoolName}</span><span className={styles.contextChip}>{snapshot.academicYearLabel || 'Contexte académique à définir'}</span></div>
    </header>

    <div className={styles.metricRail}>{snapshot.metrics.map((metric) => <article key={metric.key} className={styles.metric} data-tone={metric.tone}><span className={styles.metricLabel}>{metric.label}</span><strong className={styles.metricValue}>{metric.value}</strong><span className={styles.metricDetail}>{metric.detail}</span></article>)}</div>

    <div className={styles.commandBar}>
      <div className={styles.commandContext}><span className={styles.contextChip} style={{ color: '#24415e', background: '#f2f7fb', borderColor: '#dce6f0' }}>Période: {snapshot.period.label}</span><span className={styles.contextChip} style={{ color: '#24415e', background: '#f2f7fb', borderColor: '#dce6f0' }}>État: {snapshot.period.status}</span><span className={styles.contextChip} style={{ color: '#24415e', background: '#f2f7fb', borderColor: '#dce6f0' }}>{snapshot.exceptions.length} exception(s)</span></div>
      <div className={styles.commandActions}>{actions.map((item, index) => <button key={`${item.operationKey}:${item.title}`} type="button" className={index === 0 ? styles.primary : item.danger ? styles.danger : styles.button} onClick={() => setAction(item)}>{item.title}</button>)}</div>
    </div>

    <CustomerPlaneNavigation planes={planes} activeKey={activePlane} permissions={snapshot.permissions} entitlementKeys={snapshot.entitlementKeys}/>
    <div className={styles.surface}>{renderScene(scene, activePlane, snapshot)}</div>

    {action ? <FinanceAuthorityActionDrawer open operationKey={action.operationKey} title={action.title} description={action.description} fields={action.fields} entityId={action.entityId} onClose={() => setAction(null)} onCompleted={completed}/> : null}
  </section>
}


function resolveFinanceFields(fields: Field[], snapshot: FinanceAuthoritySnapshot): Field[] {
  return fields.map((field) => {
    if (!field.source) return field
    if (field.source === 'academicYear') {
      return { ...field, type: 'select', options: snapshot.academicYearId ? [{ value: snapshot.academicYearId, label: snapshot.academicYearLabel || 'Année scolaire active' }] : [] }
    }
    if (field.source === 'documentSources') {
      const records = [...(snapshot.records.invoices || []), ...(snapshot.records.payments || [])]
      return { ...field, type: 'select', options: records.map((record) => ({ value: record.id, label: `${record.code} — ${record.title}` })) }
    }
    const records = snapshot.records[field.source] || []
    return { ...field, type: 'select', options: records.map((record) => ({ value: record.id, label: `${record.code} — ${record.title}` })) }
  })
}

function renderScene(scene: FinanceAuthorityScene, plane: string, snapshot: FinanceAuthoritySnapshot) {
  if (scene === 'command') return <CommandScene plane={plane} snapshot={snapshot}/>
  if (scene === 'billing') return <BillingScene plane={plane} snapshot={snapshot}/>
  if (scene === 'payments') return <PaymentsScene plane={plane} snapshot={snapshot}/>
  if (scene === 'collections') return <CollectionsScene plane={plane} snapshot={snapshot}/>
  if (scene === 'expenses') return <ExpensesScene plane={plane} snapshot={snapshot}/>
  return <DocumentsScene plane={plane} snapshot={snapshot}/>
}

function CommandScene({ plane, snapshot }: { plane: string; snapshot: FinanceAuthoritySnapshot }) {
  if (plane === 'receivables') return <div className={styles.sceneGrid}><Panel title="Vieillissement des créances" subtitle="Montants réels par ancienneté et volume de factures."><Aging snapshot={snapshot}/></Panel><Panel dark title="Runway de recouvrement" subtitle="Du solde courant à la résolution documentée."><Flow steps={['Détection échéance','Qualification compte','Action et contact','Engagement ou litige','Résolution et audit']}/></Panel></div>
  if (plane === 'cash-position') return <div className={styles.sceneGrid}><Panel title="Position d’encaissement" subtitle="Flux par méthode et affectation."><div className={styles.documentGrid}>{snapshot.paymentMethods.map((item) => <article className={styles.documentCard} key={item.method}><span className={styles.documentIcon}>{item.count}</span><h3>{labelMethod(item.method)}</h3><p>{item.amount} encaissés sur cette méthode.</p></article>)}</div></Panel><Panel title="Paiements non affectés" subtitle="Affectation requise pour équilibrer les comptes."><Records records={snapshot.exceptions.filter((item) => item.status === 'unallocated')}/></Panel></div>
  if (plane === 'collections' || plane === 'commitments') return <div className={styles.sceneGrid}><Panel title={plane === 'commitments' ? 'Engagements de paiement' : 'Dossiers de recouvrement'} subtitle="Responsables, échéances et état réel."><Records records={plane === 'commitments' ? snapshot.records.commitments : snapshot.records.collectionCases}/></Panel><Panel dark title="Performance de récupération" subtitle="Objectifs et exécution observée."><Progress data={snapshot.collectionPerformance}/></Panel></div>
  if (plane === 'exceptions') return <div className={styles.sceneGrid}><Panel title="Tour de contrôle des exceptions" subtitle="Écarts bloquants ou exigeant une autorité."><Records records={snapshot.exceptions}/></Panel><Panel dark title="Discipline d’intervention" subtitle="Aucune exception financière ne doit mourir dans une liste."><Flow steps={['Qualifier la source','Assigner un propriétaire','Décider ou corriger','Exécuter la conséquence','Vérifier l’équilibre','Clôturer et auditer']}/></Panel></div>
  if (plane === 'performance') return <div className={styles.sceneGrid}><Panel title="Performance financière institutionnelle" subtitle="Collecte, affectation et respect des engagements."><Progress data={snapshot.collectionPerformance}/></Panel><Panel title="Factures récentes" subtitle="Lecture opérationnelle des derniers mouvements."><Records records={snapshot.records.invoices.slice(0, 12)}/></Panel></div>
  if (plane === 'closure') return <div className={styles.sceneGrid}><Panel dark title="Readiness de clôture" subtitle="Une période ne se ferme que si les bloqueurs sont résolus."><Flow steps={['Factures et runs stabilisés','Paiements affectés','Remboursements décidés','Dépenses approuvées','Rapprochement résolu','Clôture autorisée']}/></Panel><Panel title="Bloqueurs actuels" subtitle={`${snapshot.period.blockers} élément(s) à examiner.`}><Records records={snapshot.exceptions.slice(0, 20)}/></Panel></div>
  if (plane === 'audit') return <AuditScene snapshot={snapshot}/>
  return <div className={styles.sceneGrid}><Panel title="Priorités financières du jour" subtitle="Ce qui nécessite une action concrète maintenant."><Records records={snapshot.exceptions.length ? snapshot.exceptions.slice(0, 16) : snapshot.records.invoices.slice(0, 16)}/></Panel><Panel dark title="Chaîne financière autoritative" subtitle="Chaque étape produit un mouvement réel, une version et un audit."><Flow steps={['Doctrine et éligibilité','Facturation idempotente','Paiement capturé','Affectation équilibrée','Document versionné','Recouvrement / clôture']}/></Panel></div>
}

function BillingScene({ plane, snapshot }: { plane: string; snapshot: FinanceAuthoritySnapshot }) {
  if (plane === 'invoices') return <div className={styles.sceneGrid}><Panel title="Registre des factures" subtitle="Factures autoritatives, soldes et états."><RecordTable records={snapshot.records.invoices}/></Panel><Panel dark title="Invariants de facturation" subtitle="Émission, correction et historique sans réécriture."><Flow steps={['Lignes de frais','Sous-total contrôlé','Remises approuvées','Taxes configurées','Total invariant','Version documentaire']}/></Panel></div>
  if (plane === 'billing-runs') return <div className={styles.sceneGrid}><Panel dark title="Runway de production" subtitle="Prévisualiser avant d’écrire, exécuter sans doublon, produire un résultat par affectation."><Flow steps={['Sélection éligible','Prévisualisation','Contrôles','Approbation','Création factures','Résultats et réparation']}/></Panel><Panel title="Factures produites récemment" subtitle="Les dernières sorties de production."><Records records={snapshot.records.invoices.slice(0, 14)}/></Panel></div>
  if (plane === 'credits') return <div className={styles.sceneGrid}><Panel title="Avoirs et corrections" subtitle="Correction financière par document, jamais par effacement."><Records records={snapshot.records.approvals.filter((item) => item.code.includes('finance.invoice'))}/></Panel><Panel dark title="Correction gouvernée" subtitle="L’original reste historisable."><Flow steps={['Facture source','Demande et motif','Impact prévisualisé','Approbation','Avoir / remplacement','Ledger et audit']}/></Panel></div>
  if (plane === 'assignments' || plane === 'eligibility') return <div className={styles.sceneGrid}><Panel title={plane === 'eligibility' ? 'Matrice d’éligibilité' : 'Affectations de frais'} subtitle="Population, contexte académique et dates effectives."><EligibilityMatrix snapshot={snapshot}/></Panel><Panel dark title="Contrôles d’affectation" subtitle="Prévenir doublons, conflits de version et affectations invalides."><Flow steps={['Élève actif','Contexte valide','Doctrine publiée','Aucun doublon','Capacité disponible','Affectation historisée']}/></Panel></div>
  if (plane === 'installments') return <div className={styles.sceneGrid}><Panel title="Échéanciers structurés" subtitle="Plans, dépôts, échéances et restructurations versionnées."><Records records={snapshot.records.approvals.filter((item) => item.code.includes('installment'))}/></Panel><Panel dark title="Lifecycle échéancier" subtitle="Aucune réécriture silencieuse des échéances facturées."><Flow steps={['Brouillon','Proposé','Accepté','Actif','Partiellement payé','Terminé / restructuré']}/></Panel></div>
  if (plane === 'audit') return <AuditScene snapshot={snapshot}/>
  return <div className={styles.sceneGrid}><Panel title={plane === 'fee-catalogue' ? 'Catalogue de frais' : plane === 'versions' ? 'Versions publiées' : 'Doctrine financière'} subtitle="Définition versionnée, effective-dated et non destructive."><DoctrineCanvas records={snapshot.records.feeStructures}/></Panel><Panel dark title="Architecture de facturation" subtitle="La doctrine pilote l’éligibilité, l’affectation et la production."><Flow steps={['Définition du frais','Version et dates','Règles éligibilité','Affectations','Run de facturation','Facture immutable']}/></Panel></div>
}

function PaymentsScene({ plane, snapshot }: { plane: string; snapshot: FinanceAuthoritySnapshot }) {
  if (plane === 'allocation' || plane === 'unallocated') return <div className={styles.sceneGrid}><Panel title={plane === 'allocation' ? 'Carte d’affectation des paiements' : 'Paiements non affectés'} subtitle="Montant payé = affecté + disponible − reversé."><Records records={plane === 'unallocated' ? snapshot.exceptions.filter((item) => item.status === 'unallocated') : snapshot.records.payments}/></Panel><Panel dark title="Invariant d’affectation" subtitle="La réaffectation crée une révision avant/après."><Flow steps={['Paiement confirmé','Solde disponible','Facture(s) sélectionnée(s)','Affectation contrôlée','Balances recalculées','Reçu révisé si nécessaire']}/></Panel></div>
  if (plane === 'receipts') return <div className={styles.sceneGrid}><Panel title="Autorité des reçus" subtitle="Chaque reçu est rattaché à un paiement et un document versionné."><Records records={snapshot.records.receipts}/></Panel><Panel title="Documents de paiement" subtitle="Sorties générées avec version et empreinte."><Records records={snapshot.records.documents.filter((item) => item.subtitle.includes('receipt') || item.subtitle.includes('payment'))}/></Panel></div>
  if (plane === 'refunds') return <div className={styles.sceneGrid}><Panel title="Remboursements" subtitle="Demande, approbation, exécution et rapprochement sans effacer la source."><Records records={snapshot.records.refunds}/></Panel><Panel dark title="Lifecycle remboursement" subtitle="Le paiement source reste intact."><Flow steps={['Demande','Revue','Approbation','Exécution','Rapprochement','Clôture']}/></Panel></div>
  if (plane === 'reconciliation' || plane === 'settlements') return <div className={styles.sceneGrid}><Panel dark title="Rapprochement des flux" subtitle="Comparer référence, montant, date, payeur et règlement."><Flow steps={['Importer / capturer','Proposer match','Vérifier différences','Décider','Réconcilier','Conserver preuve']}/></Panel><Panel title="Écarts et exceptions" subtitle="Différences nécessitant une intervention."><Records records={snapshot.exceptions.filter((item) => ['warning','critical'].includes(item.tone))}/></Panel></div>
  if (plane === 'audit') return <AuditScene snapshot={snapshot}/>
  return <div className={styles.sceneGrid}><Panel title={plane === 'capture' ? 'Capture de paiement' : 'Commandement paiements'} subtitle="Référence, méthode, montant, affectation et état."><RecordTable records={snapshot.records.payments}/></Panel><Panel title="Mix d’encaissement" subtitle="Volumes et montants par méthode."><div className={styles.documentGrid}>{snapshot.paymentMethods.map((item) => <article key={item.method} className={styles.documentCard}><span className={styles.documentIcon}>{item.count}</span><h3>{labelMethod(item.method)}</h3><p>{item.amount}</p></article>)}</div></Panel></div>
}

function CollectionsScene({ plane, snapshot }: { plane: string; snapshot: FinanceAuthoritySnapshot }) {
  if (plane === 'aging') return <div className={styles.sceneGrid}><Panel title="Aging des comptes" subtitle="Créances configurables par ancienneté."><Aging snapshot={snapshot}/></Panel><Panel dark title="Priorisation" subtitle="Le montant seul ne décide pas: âge, engagement, litige et historique comptent."><Flow steps={['Compte et payeur','Âge de créance','Engagement actif','Litige éventuel','Prochaine action','Direction si exception']}/></Panel></div>
  if (plane === 'commitments') return <div className={styles.sceneGrid}><Panel title="Engagements de paiement" subtitle="Montants, échéances, tenue ou rupture."><Records records={snapshot.records.commitments}/></Panel><Panel dark title="Surveillance des promesses" subtitle="Une échéance rompue crée une exception gouvernée."><Flow steps={['Proposé','Accepté','Actif','Partiellement tenu','Tenu / rompu','Renégocié ou escaladé']}/></Panel></div>
  if (plane === 'statements') return <div className={styles.sceneGrid}><Panel title="Relevés de compte" subtitle="Documents générés depuis le ledger réel."><Records records={snapshot.records.documents.filter((item) => item.subtitle.includes('statement') || item.title.toLowerCase().includes('compte'))}/></Panel><Panel dark title="Contenu du relevé" subtitle="Ouverture, charges, paiements, crédits, remboursements et solde."><Flow steps={['Solde ouverture','Charges / factures','Paiements affectés','Crédits et avoirs','Remboursements','Solde clôture']}/></Panel></div>
  if (plane === 'recovery-performance') return <div className={styles.sceneGrid}><Panel title="Performance du recouvrement" subtitle="Collecte, affectation et promesses tenues."><Progress data={snapshot.collectionPerformance}/></Panel><Panel title="Dossiers récents" subtitle="État des interventions en cours."><Records records={snapshot.records.collectionCases}/></Panel></div>
  if (plane === 'audit') return <AuditScene snapshot={snapshot}/>
  const source = plane === 'accounts' ? snapshot.records.balances : plane === 'overdue' ? snapshot.records.invoices.filter((item) => item.status === 'overdue') : plane === 'disputes' ? snapshot.records.approvals.filter((item) => item.code.includes('dispute')) : snapshot.records.collectionCases
  return <div className={styles.sceneGrid}><Panel title={plane === 'accounts' ? 'Comptes étudiants et payeurs' : plane === 'overdue' ? 'Créances en retard' : plane === 'disputes' ? 'Litiges financiers' : 'Interventions de recouvrement'} subtitle="Contexte financier complet, prochaine action et responsabilité."><RecordTable records={source}/></Panel><Panel dark title="Recovery control loop" subtitle="Chaque intervention doit conduire à un état financier vérifiable."><Flow steps={['Identifier le compte','Qualifier la créance','Contacter et documenter','Engagement ou litige','Conséquence financière','Clôture et audit']}/></Panel></div>
}

function ExpensesScene({ plane, snapshot }: { plane: string; snapshot: FinanceAuthoritySnapshot }) {
  if (plane === 'periods' || plane === 'closure') return <div className={styles.sceneGrid}><Panel dark title={plane === 'closure' ? 'Clôture financière opérationnelle' : 'Périodes financières'} subtitle="Verrouillage serveur, réouverture autorisée et re-clôture obligatoire."><Flow steps={['Ouverte','Revue','Clôture demandée','Bloqueurs résolus','Clôturée','Réouverte / re-clôturée']}/></Panel><Panel title="Readiness actuelle" subtitle={`${snapshot.period.blockers} bloqueur(s) détecté(s).`}><Records records={snapshot.exceptions.slice(0, 20)}/></Panel></div>
  if (plane === 'approvals') return <div className={styles.sceneGrid}><Panel title="Approbations financières" subtitle="Seuils, séparation des tâches et conséquences réelles."><Records records={snapshot.records.approvals}/></Panel><Panel dark title="Segregation of duties" subtitle="Auteur, collecteur, allocateur, approbateur et clôtureur peuvent être séparés."><Flow steps={['Soumission','Contrôle autorité','Décision','Exécution conséquence','Vérification','Audit']}/></Panel></div>
  if (plane === 'reconciliation') return <div className={styles.sceneGrid}><Panel title="Rapprochement dépenses" subtitle="Dépense, paiement, preuve et état de rapprochement."><Records records={snapshot.records.expenses.filter((item) => item.status === 'paid')}/></Panel><Panel dark title="Preuve de dépense" subtitle="Aucune dépense payée sans trace de validation et justificatif."><Flow steps={['Demande','Justificatif','Approbation','Paiement','Rapprochement','Archivage']}/></Panel></div>
  if (plane === 'audit') return <AuditScene snapshot={snapshot}/>
  return <div className={styles.sceneGrid}><Panel title={plane === 'requests' ? 'Demandes de dépenses' : plane === 'evidence' ? 'Justificatifs' : plane === 'expense-command' ? 'Commandement dépenses' : 'Registre dépenses'} subtitle="Dépenses opérationnelles, statuts, responsables et montants."><RecordTable records={snapshot.records.expenses}/></Panel><Panel dark title="Lifecycle dépense" subtitle="La dépense approuvée ne se réécrit pas silencieusement."><Flow steps={['Brouillon','Soumise','Revue','Approuvée','Paiement','Rapprochée']}/></Panel></div>
}

function DocumentsScene({ plane, snapshot }: { plane: string; snapshot: FinanceAuthoritySnapshot }) {
  if (plane === 'templates') return <div className={styles.sceneGrid}><Panel title="Autorité des templates" subtitle="Version, langue, portée et contrat de données."><TemplateCards records={snapshot.records.templates || []}/></Panel><Panel dark title="Publication template" subtitle="Chaque document conserve la version exacte utilisée."><Flow steps={['Brouillon template','Validation data contract','Publication','Affectation institution','Génération','Remplacement versionné']}/></Panel></div>
  if (plane === 'generated' || plane === 'publication-history') return <div className={styles.sceneGrid}><Panel title={plane === 'generated' ? 'Documents générés' : 'Historique de publication'} subtitle="Documents privés, versionnés et empreintés."><Records records={snapshot.records.documents}/></Panel><Panel dark title="Immutabilité documentaire" subtitle="L’historique ne se régénère pas depuis des données actuelles."><Flow steps={['Source + revision','Template version','Génération PDF','Checksum','Publication','Supersession si correction']}/></Panel></div>
  if (plane === 'report-catalogue' || plane === 'requests' || plane === 'scheduled') return <div className={styles.sceneGrid}><Panel title={plane === 'report-catalogue' ? 'Catalogue des rapports' : plane === 'requests' ? 'Runs de rapports' : 'Rapports planifiés'} subtitle="Rapports standards et exécutions bornées.">{plane === 'report-catalogue' ? <ReportCatalogue/> : <Records records={snapshot.records.reportRuns}/>}</Panel><Panel dark title="Exécution réelle" subtitle="Les gros volumes passent par une file avec progression vérifiable."><Flow steps={['Demande et permission','Périmètre tenant','File background','Progression réelle','Fichier sécurisé','Expiration et audit']}/></Panel></div>
  if (plane === 'exports') return <div className={styles.sceneGrid}><Panel title="Exports contrôlés" subtitle="CSV, XLSX, PDF et formats d’intégration."><Records records={snapshot.records.exportRuns}/></Panel><Panel dark title="Contrat export" subtitle="Périmètre, sensibilité, rétention et expiration obligatoires."><Flow steps={['Permission','Filtres et période','Volume borné','Génération','Téléchargement sécurisé','Expiration']}/></Panel></div>
  if (plane === 'retention') return <div className={styles.sceneGrid}><Panel title="Rétention et conformité" subtitle="Conservation, restriction, supersession et expiration."><RetentionMatrix/></Panel><Panel dark title="Historique financier" subtitle="Archiver ou superséder, jamais effacer arbitrairement."><Flow steps={['Classification','Durée de conservation','Restriction accès','Expiration téléchargement','Archivage','Audit']}/></Panel></div>
  if (plane === 'audit') return <AuditScene snapshot={snapshot}/>
  return <div className={styles.sceneGrid}><Panel title="Commandement documentaire" subtitle="Production, rapports, exports et conformité."><div className={styles.documentGrid}>{['Factures','Reçus','États de compte','Avoirs','Rapports','Exports'].map((title, index) => <article className={styles.documentCard} key={title}><span className={styles.documentIcon}>{String(index + 1).padStart(2,'0')}</span><h3>{title}</h3><p>Version, source, empreinte, stockage privé et publication contrôlée.</p></article>)}</div></Panel><Panel title="Dernières productions" subtitle="Documents et runs récemment gouvernés."><Records records={[...snapshot.records.documents, ...snapshot.records.reportRuns, ...snapshot.records.exportRuns].slice(0, 16)}/></Panel></div>
}

function AuditScene({ snapshot }: { snapshot: FinanceAuthoritySnapshot }) { return <div className={styles.sceneGrid}><Panel title="Chronologie des exécutions" subtitle="Opérations financières, états et résultats."><Records records={snapshot.records.executions}/></Panel><Panel title="Approbations et décisions" subtitle="Demandes, décisions et conséquences réelles."><Records records={snapshot.records.approvals}/></Panel></div> }
function Panel({ title, subtitle, children, dark = false }: { title: string; subtitle: string; children: React.ReactNode; dark?: boolean }) { return <section className={dark ? styles.panelDark : styles.panel}><header className={styles.panelHead}><div><h2>{title}</h2><p>{subtitle}</p></div></header><div className={styles.panelBody}>{children}</div></section> }
function Records({ records }: { records: FinanceAuthorityRecord[] }) { if (!records.length) return <div className={styles.empty}><div><strong>Aucun enregistrement dans ce plan</strong><p>La vue restera vide tant qu’aucune opération autoritative n’est créée.</p></div></div>; return <div className={styles.stack}>{records.slice(0, 24).map((record) => <article className={styles.record} key={record.id}><div className={styles.recordMain}><div className={styles.recordTitle}><span>{record.code}</span><span className={styles.status} data-tone={record.tone}>{record.status}</span></div><div className={styles.recordSubtitle}>{record.title} · {record.subtitle}</div></div><div className={styles.recordSide}>{record.amount ? <div className={styles.amount}>{record.amount}</div> : null}{record.date ? <div className={styles.recordSubtitle}>{record.date.slice(0,10)}</div> : null}</div></article>)}</div> }
function RecordTable({ records }: { records: FinanceAuthorityRecord[] }) { if (!records.length) return <Records records={records}/>; return <div className={styles.tableWrap}><table className={styles.matrix}><thead><tr><th>Référence</th><th>Entité</th><th>État</th><th>Date</th><th>Montant</th></tr></thead><tbody>{records.slice(0,100).map((record) => <tr key={record.id}><td><strong>{record.code}</strong></td><td>{record.title}<div className={styles.recordSubtitle}>{record.subtitle}</div></td><td><span className={styles.status} data-tone={record.tone}>{record.status}</span></td><td>{record.date?.slice(0,10) || '—'}</td><td><strong>{record.amount || '—'}</strong></td></tr>)}</tbody></table></div> }
function Aging({ snapshot }: { snapshot: FinanceAuthoritySnapshot }) { const max = Math.max(1, ...snapshot.aging.map((item) => Number(item.amount.replace(/[^0-9,.-]/g,'').replace(',','.')) || 0)); return <div className={styles.agingGrid}>{snapshot.aging.map((item) => { const amount = Number(item.amount.replace(/[^0-9,.-]/g,'').replace(',','.')) || 0; return <article className={styles.agingCard} data-tone={item.tone} key={item.bucket}><span>{item.bucket}</span><strong>{item.amount}</strong><span>{item.invoices} facture(s)</span><div className={styles.agingBar}><i style={{ width: `${Math.max(4, amount / max * 100)}%` }}/></div></article> })}</div> }
function Flow({ steps }: { steps: string[] }) { return <div className={styles.flow}>{steps.map((step, index) => <div className={styles.flowStep} key={step}><span className={styles.flowIndex}>{String(index + 1).padStart(2,'0')}</span><strong>{step}</strong><span className={styles.flowState}>{index === 0 ? 'source' : index === steps.length - 1 ? 'preuve' : 'contrôle'}</span></div>)}</div> }
function Progress({ data }: { data: Array<{ label: string; value: number; target: number }> }) { return <div className={styles.progressList}>{data.map((item) => <div className={styles.progressRow} key={item.label}><span>{item.label}</span><div className={styles.progressTrack}><i style={{ width: `${Math.max(0,Math.min(100,item.value))}%` }}/></div><strong>{item.value}%</strong></div>)}</div> }
function DoctrineCanvas({ records }: { records: FinanceAuthorityRecord[] }) {
  if (!records.length) return <div className={styles.empty}><div><strong>Aucune doctrine de frais publiée</strong><p>Créez une structure réelle, ajoutez ses lignes tarifaires puis publiez une version effective.</p></div></div>
  return <div className={styles.documentGrid}>{records.slice(0, 12).map((record, index) => <article className={styles.documentCard} key={record.id}><span className={styles.documentIcon}>V{String(index + 1).padStart(2,'0')}</span><h3>{record.title}</h3><p>{record.code} · {record.status}{record.date ? ` · ${record.date.slice(0,10)}` : ''}</p>{record.amount ? <strong>{record.amount}</strong> : null}</article>)}</div>
}
function EligibilityMatrix({ snapshot }: { snapshot: FinanceAuthoritySnapshot }) {
  const records = snapshot.records.feeAssignments || []
  if (!records.length) return <div className={styles.empty}><div><strong>Aucune affectation de frais</strong><p>La matrice se remplit uniquement depuis les affectations autoritatives du tenant.</p></div></div>
  return <div className={styles.tableWrap}><table className={styles.matrix}><thead><tr><th>Référence</th><th>Élève / compte</th><th>Doctrine</th><th>État</th><th>Date</th></tr></thead><tbody>{records.slice(0,100).map((record) => <tr key={record.id}><td><strong>{record.code}</strong></td><td>{record.title}<div className={styles.recordSubtitle}>{record.subtitle}</div></td><td>{String(record.meta?.feeStructureLabel || record.meta?.feeStructureCode || 'Structure rattachée')}</td><td><span className={styles.status} data-tone={record.tone}>{record.status}</span></td><td>{record.date?.slice(0,10) || '—'}</td></tr>)}</tbody></table></div>
}
function TemplateCards({ records }: { records: FinanceAuthorityRecord[] }) {
  if (!records.length) return <div className={styles.empty}><div><strong>Aucun template financier publié</strong><p>Publiez une version de facture, reçu, avoir ou relevé avant toute génération.</p></div></div>
  return <div className={styles.documentGrid}>{records.slice(0, 12).map((record, index)=><article className={styles.documentCard} key={record.id}><span className={styles.documentIcon}>T{String(index+1).padStart(2,'0')}</span><h3>{record.title}</h3><p>{record.code} · {record.status}{record.date ? ` · ${record.date.slice(0,10)}` : ''}</p></article>)}</div>
}
function ReportCatalogue() { return <div className={styles.documentGrid}>{['Factures émises','Encaissements','Créances vieillies','Performance recouvrement','Remises & aides','Dépenses & clôture'].map((title,index)=><article className={styles.documentCard} key={title}><span className={styles.documentIcon}>R{index+1}</span><h3>{title}</h3><p>Définition standard disponible dans le catalogue produit; l’exécution reste tenant-scoped, permissionnée et auditée.</p></article>)}</div> }
function RetentionMatrix() { const rows=[['Document','Conservation','Accès','Sortie'],['Facture','Selon policy tenant','Finance + audit','Archive / supersession'],['Reçu','Selon policy tenant','Finance + payeur autorisé','Archive'],['Export','Expiration courte','Demandeur autorisé','Suppression fichier, audit conservé'],['Audit','Long terme','Auditeur autorisé','Immuable']]; return <div className={styles.tableWrap}><table className={styles.matrix}><thead><tr>{rows[0].map((cell)=><th key={cell}>{cell}</th>)}</tr></thead><tbody>{rows.slice(1).map((row,index)=><tr key={index}>{row.map((cell)=><td key={cell}>{cell}</td>)}</tr>)}</tbody></table></div> }
function labelMethod(method: string) { return ({ cash:'Espèces',transfer:'Virement',cheque:'Chèque',card:'Carte',direct_debit:'Prélèvement',mobile:'Paiement mobile',credit_balance:'Crédit compte',sponsor:'Sponsor',other:'Autre' } as Record<string,string>)[method] || method }
